export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  relativePath: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
  url: string;
}

export interface SiteConfig {
  title: string;
  description: string;
  url: string;
  author?: string;
  language?: string;
}

export interface TemplateContext {
  title: string;
  date?: string;
  tags?: string[];
  content: string;
  page: Page;
  pages: Page[];
  site: SiteConfig;
}

export interface TagIndexContext {
  tag: string;
  posts: Page[];
  site: SiteConfig;
  title: string;
  pages: Page[];
}

export interface CLIOptions {
  source: string;
  template: string;
  output: string;
  serve: boolean;
  port: number;
  siteConfig: string;
}

import fs from "fs";
import path from "path";
import matter from "gray-matter";
import { Frontmatter, Page } from "./types";

export function parseFrontmatter(filePath: string): {
  frontmatter: Frontmatter;
  content: string;
} {
  const raw = fs.readFileSync(filePath, "utf-8");
  const { data, content } = matter(raw);
  const fm = data as Frontmatter;

  if (fm.draft === undefined) {
    fm.draft = false;
  }

  return { frontmatter: fm, content };
}

export function resolvePages(sourceDir: string, basePath: string = ""): Page[] {
  const pages: Page[] = [];
  const entries = fs.readdirSync(sourceDir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(sourceDir, entry.name);
    if (entry.isDirectory()) {
      pages.push(...resolvePages(fullPath, path.join(basePath, entry.name)));
    } else if (entry.isFile() && entry.name.endsWith(".md")) {
      pages.push(processMarkdownFile(fullPath, basePath, sourceDir));
    }
  }

  return pages;
}

function processMarkdownFile(
  filePath: string,
  basePath: string,
  sourceDir: string
): Page {
  const { frontmatter, content } = parseFrontmatter(filePath);
  const relativePath = filePath.replace(sourceDir + path.sep, "");
  const slug = relativePath.replace(/\.md$/, "").replace(/\\/g, "/");
  const fileName = path.basename(filePath, ".md");
  const dir = basePath ? basePath.replace(/\\/g, "/") : "";

  let url: string;
  if (fileName === "index") {
    url = dir ? `/${dir}/` : "/";
  } else {
    url = dir ? `/${dir}/${fileName}/` : `/${fileName}/`;
  }

  return {
    path: filePath,
    relativePath,
    frontmatter,
    content,
    html: "",
    url,
  };
}

export function getPublishedPages(pages: Page[]): Page[] {
  return pages.filter((p) => !p.frontmatter.draft);
}

export function getSortedPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    const dateA = a.frontmatter.date
      ? new Date(a.frontmatter.date).getTime()
      : 0;
    const dateB = b.frontmatter.date
      ? new Date(b.frontmatter.date).getTime()
      : 0;
    return dateB - dateA;
  });
}

export function getTags(pages: Page[]): Map<string, Page[]> {
  const tagMap = new Map<string, Page[]>();
  for (const page of pages) {
    const tags = page.frontmatter.tags;
    if (tags) {
      for (const tag of tags) {
        const existing = tagMap.get(tag) || [];
        existing.push(page);
        tagMap.set(tag, existing);
      }
    }
  }
  return tagMap;
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return hljs.highlightAuto(code).value;
    },
  })
);

marked.setOptions({
  gfm: true,
  breaks: false,
});

export function renderMarkdown(content: string): string {
  return marked.parse(content) as string;
}

import fs from "fs";
import path from "path";
import Handlebars from "handlebars";
import handlebarsLayouts from "handlebars-layouts";

handlebarsLayouts.register(Handlebars);

Handlebars.registerHelper("formatDate", function (date: string) {
  if (!date) return "";
  const d = new Date(date);
  return d.toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });
});

Handlebars.registerHelper("eq", function (a: unknown, b: unknown) {
  return a === b;
});

Handlebars.registerHelper("hasTag", function (
  tags: string[] | undefined,
  tag: string
) {
  if (!tags) return false;
  return tags.includes(tag);
});

export interface TemplateEngine {
  render(
    templateName: string,
    context: Record<string, unknown>
  ): string;
}

export function createTemplateEngine(templateDir: string): TemplateEngine {
  const templates = new Map<string, HandlebarsTemplateDelegate>();

  function loadTemplates(dir: string, prefix: string = ""): void {
    if (!fs.existsSync(dir)) return;
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        loadTemplates(fullPath, prefix + entry.name + "/");
      } else if (entry.isFile() && entry.name.endsWith(".hbs")) {
        const name = prefix + entry.name.replace(/\.hbs$/, "");
        const source = fs.readFileSync(fullPath, "utf-8");
        templates.set(name, Handlebars.compile(source));
      }
    }
  }

  function loadPartials(dir: string): void {
    if (!fs.existsSync(dir)) return;
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        loadPartials(fullPath);
      } else if (entry.isFile() && entry.name.endsWith(".hbs")) {
        const name = entry.name.replace(/\.hbs$/, "partials/");
        const source = fs.readFileSync(fullPath, "utf-8");
        Handlebars.registerPartial(name, source);
      }
    }
  }

  const partialsDir = path.join(templateDir, "partials");
  if (fs.existsSync(partialsDir)) {
    loadPartials(partialsDir);
  }

  const layoutsDir = path.join(templateDir, "layouts");
  if (fs.existsSync(layoutsDir)) {
    loadTemplates(layoutsDir, "layouts/");
  }

  loadTemplates(templateDir);

  return {
    render(
      templateName: string,
      context: Record<string, unknown>
    ): string {
      const tpl = templates.get(templateName);
      if (!tpl) {
        throw new Error(
          `Template "${templateName}" not found. Available: ${[
            ...templates.keys(),
          ].join(", ")}`
        );
      }

      const layout = Handlebars.compile(
        '{{#extend "' + templateName + '"}}{{/extend}}'
      );
      return layout(context);
    },
  };
}

