      } else if (entry.isFile() && entry.name.endsWith(".hbs")) {
        const name = prefix + entry.name.replace(/\.hbs$/, "");
        const source = fs.readFileSync(fullPath, "utf-8");
        templateCache.set(name, Handlebars.compile(source));
      }
    }
  }

  function loadPartials(dir: string): void {
    if (!fs.existsSync(dir)) return;
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        loadPartials(fullPath);
      } else if (entry.isFile() && entry.name.endsWith(".hbs")) {
        const name = entry.name.replace(/\.hbs$/, "");
        const source = fs.readFileSync(fullPath, "utf-8");
        Handlebars.registerPartial(name, source);
      }
    }
  }

  const partialsDir = path.join(templateDir, "partials");
  loadPartials(partialsDir);

  loadDir(templateDir);

  function getTemplate(name: string): HandlebarsTemplateDelegate {
    const tpl = templateCache.get(name);
    if (!tpl) {
      throw new Error(
        `Template "${name}" not found. Available: ${[...templateCache.keys()].join(", ")}`
      );
    }
    return tpl;
  }

  return {
    render(templateName: string, context: Record<string, unknown>): string {
      return getTemplate(templateName)(context);
    },

    renderWithLayout(
      templateName: string,
      layoutName: string,
      context: Record<string, unknown>
    ): string {
      const bodyContent = getTemplate(templateName)(context);
      const layoutContext = {
        ...context,
        body: bodyContent,
      };
      return getTemplate(layoutName)(layoutContext);
    },
  };
}

import { Page, SiteConfig } from "./types";

function escapeXml(str: string): string {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

export function generateRSS(
  pages: Page[],
  siteConfig: SiteConfig,
  baseUrl: string
): string {
  const items = pages
    .filter((p) => !p.frontmatter.draft && p.frontmatter.date)
    .sort((a, b) => {
      const dateA = new Date(a.frontmatter.date!).getTime();
      const dateB = new Date(b.frontmatter.date!).getTime();
      return dateB - dateA;
    })
    .slice(0, 20)
    .map((p) => {
      const url = baseUrl.replace(/\/$/, "") + p.url;
      const date = new Date(p.frontmatter.date!);
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid isPermaLink="true">${escapeXml(url)}</guid>
      <pubDate>${date.toUTCString()}</pubDate>
      <description>${escapeXml(p.html.slice(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  const now = new Date().toUTCString();

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(siteConfig.title)}</title>
    <description>${escapeXml(siteConfig.description)}</description>
    <link>${escapeXml(baseUrl)}</link>
    <atom:link href="${escapeXml(baseUrl.replace(/\/$/, "") + "/feed.xml")}" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${now}</lastBuildDate>
${items}
  </channel>
</rss>`;
}

import fs from "fs";
import path from "path";
import { Page, SiteConfig, TemplateContext, TagIndexContext } from "./types";
import { resolvePages, getPublishedPages, getSortedPages, getTags } from "./frontmatter";
import { renderMarkdown } from "./markdown";
import { createTemplateEngine } from "./templates";
import { generateRSS } from "./rss";

export interface GeneratorOptions {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteConfig: SiteConfig;
}

export function generate(options: GeneratorOptions): void {
  const { sourceDir, templateDir, outputDir, siteConfig } = options;
  const engine = createTemplateEngine(templateDir);

  if (fs.existsSync(outputDir)) {
    fs.rmSync(outputDir, { recursive: true });
  }
  fs.mkdirSync(outputDir, { recursive: true });

  const allPages = resolvePages(sourceDir);
  const publishedPages = getPublishedPages(allPages);

  for (const page of publishedPages) {
    page.html = renderMarkdown(page.content);
  }

  const sortedPages = getSortedPages(publishedPages);

  for (const page of publishedPages) {
    const templateName = page.frontmatter.layout || "post";
    const layoutName = "layouts/default";
    const context: TemplateContext = {
      title: page.frontmatter.title,
      date: page.frontmatter.date,
      tags: page.frontmatter.tags,
      content: page.html,
      page,
      pages: sortedPages,
      site: siteConfig,
    };

    let html: string;
    try {
      html = engine.renderWithLayout(templateName, layoutName, context);
    } catch {
      html = engine.render(templateName, context);
    }

    const outPath = path.join(outputDir, page.url);
    fs.mkdirSync(outPath, { recursive: true });
    fs.writeFileSync(path.join(outPath, "index.html"), html);
  }

  copyStaticAssets(templateDir, outputDir);

  const tags = getTags(sortedPages);
  if (tags.size > 0) {
    const tagsDir = path.join(outputDir, "tags");
    fs.mkdirSync(tagsDir, { recursive: true });

    for (const [tag, tagPages] of tags) {
      const context: TagIndexContext = {
        tag,
        posts: tagPages,
        site: siteConfig,
        title: `Posts tagged "${tag}"`,
        pages: sortedPages,
      };

      let html: string;
      try {
        html = engine.renderWithLayout("tag", "layouts/default", context);
      } catch {
        html = engine.render("tag", context);
      }

      const tagOutDir = path.join(tagsDir, tag);
      fs.mkdirSync(tagOutDir, { recursive: true });
      fs.writeFileSync(path.join(tagOutDir, "index.html"), html);
    }
  }

  if (sortedPages.length > 0) {
    const feed = generateRSS(sortedPages, siteConfig, siteConfig.url);
    fs.writeFileSync(path.join(outputDir, "feed.xml"), feed);
  }
}

function copyStaticAssets(templateDir: string, outputDir: string): void {
  const assetsDir = path.join(templateDir, "assets");
  if (!fs.existsSync(assetsDir)) return;
  copyRecursive(assetsDir, outputDir);
}

function copyRecursive(src: string, dest: string): void {
  fs.mkdirSync(dest, { recursive: true });
  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyRecursive(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

import http from "http";
import fs from "fs";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      location.reload();
    }
  };
  ws.onclose = function() {
    setTimeout(function() {
      location.reload();
    }, 2000);
  };
})();
</script>
`;

function injectReloadScript(html: string): string {
  if (html.includes("</body>")) {
    return html.replace("</body>", RELOAD_SCRIPT + "</body>");
  }
  return html + RELOAD_SCRIPT;
}

const MIME_TYPES: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".xml": "application/xml",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
};

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return MIME_TYPES[ext] || "application/octet-stream";
}

export function startDevServer(
  outputDir: string,
  sourceDir: string,
  templateDir: string,
  port: number,
  onRebuild: () => void
): void {
  const sockets = new Set<WebSocket>();

  const server = http.createServer((req, res) => {
    let filePath = path.join(outputDir, req.url || "/");
    if (req.url && req.url.endsWith("/")) {
      filePath = path.join(filePath, "index.html");
    }

    if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
      filePath = path.join(outputDir, "index.html");
    }

    try {
      const content = fs.readFileSync(filePath);
      const mime = getMimeType(filePath);
      res.writeHead(200, { "Content-Type": mime });

      if (mime === "text/html") {
        res.end(injectReloadScript(content.toString()));
      } else {
        res.end(content);
      }
    } catch {
      res.writeHead(404);
      res.end("Not Found");
    }
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws) => {
    sockets.add(ws);
    ws.on("close", () => sockets.delete(ws));
  });

  function broadcastReload(): void {
    for (const ws of sockets) {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send("reload");
      }
    }
  }

  const watchDirs = [
    path.resolve(sourceDir),
    path.resolve(templateDir),
  ];

  const watcher = chokidar.watch(watchDirs, {
    ignoreInitial: true,
    awaitWriteFinish: {
      stabilityThreshold: 100,
      pollInterval: 50,
    },
  });

  watcher.on("all", (_event: string, _filePath: string) => {
    try {
      onRebuild();
      broadcastReload();
    } catch (err) {
      console.error("Rebuild error:", err instanceof Error ? err.message : err);
    }
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });
}

#!/usr/bin/env node

import { Command } from "commander";
import fs from "fs";
import path from "path";
import { generate } from "./generator";
import { startDevServer } from "./server";
import { SiteConfig } from "./types";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator")
  .requiredOption("--source <dir>", "Source directory of Markdown files")
  .requiredOption("--template <dir>", "Template directory of Handlebars files")
  .requiredOption("--output <dir>", "Output directory for generated HTML")
  .option("--serve", "Start a dev server with live reload")
  .option("--port <num>", "Port for dev server", "3000")
  .option("--site-config <path>", "Path to site config JSON file")
  .action(async (options) => {
    const sourceDir = path.resolve(options.source);
    const templateDir = path.resolve(options.template);
    const outputDir = path.resolve(options.output);
    const port = parseInt(options.port, 10);

    let siteConfig: SiteConfig = {
      title: "My Site",
      description: "A static site",
      url: `http://localhost:${port}`,
    };

    if (options.siteConfig) {
      const configPath = path.resolve(options.siteConfig);
      if (fs.existsSync(configPath)) {
        siteConfig = {
          ...siteConfig,
          ...JSON.parse(fs.readFileSync(configPath, "utf-8")),
        };
      }
    }

    if (!fs.existsSync(sourceDir)) {
      console.error(`Source directory not found: ${sourceDir}`);
      process.exit(1);
    }
    if (!fs.existsSync(templateDir)) {
      console.error(`Template directory not found: ${templateDir}`);
      process.exit(1);
    }

    const build = () =>
      generate({ sourceDir, templateDir, outputDir, siteConfig });

    build();
    console.log(`Site built to ${outputDir}`);

    if (options.serve) {
      startDevServer(outputDir, sourceDir, templateDir, port, build);
    }
  });

program.parse();

